/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var Mark = require( '@stdlib/plot/vega/mark/base/ctor' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAlign = require( './align/get.js' );
var setAlign = require( './align/set.js' );

var getAngle = require( './angle/get.js' );
var setAngle = require( './angle/set.js' );

var getBaseline = require( './baseline/get.js' );
var setBaseline = require( './baseline/set.js' );

var getDir = require( './dir/get.js' );
var setDir = require( './dir/set.js' );

var getDx = require( './dx/get.js' );
var setDx = require( './dx/set.js' );

var getDy = require( './dy/get.js' );
var setDy = require( './dy/set.js' );

var getEllipsis = require( './ellipsis/get.js' );
var setEllipsis = require( './ellipsis/set.js' );

var getFont = require( './font/get.js' );
var setFont = require( './font/set.js' );

var getFontSize = require( './font-size/get.js' );
var setFontSize = require( './font-size/set.js' );

var getFontStyle = require( './font-style/get.js' );
var setFontStyle = require( './font-style/set.js' );

var getFontWeight = require( './font-weight/get.js' );
var setFontWeight = require( './font-weight/set.js' );

var getLimit = require( './limit/get.js' );
var setLimit = require( './limit/set.js' );

var getLineBreak = require( './line-break/get.js' );
var setLineBreak = require( './line-break/set.js' );

var getLineHeight = require( './line-height/get.js' );
var setLineHeight = require( './line-height/set.js' );

var getProperties = require( './properties/get.js' );

var getRadius = require( './radius/get.js' );
var setRadius = require( './radius/set.js' );

var getText = require( './text/get.js' );
var setText = require( './text/set.js' );

var getTheta = require( './theta/get.js' );
var setTheta = require( './theta/set.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );

var TYPE = require( './type/type.js' );


// VARIABLES //

var debug = logger( 'vega:text-mark:main' );


// MAIN //

/**
* Text mark constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {string} [options.align='left'] - horizontal text alignment
* @param {number} [options.angle=0] - rotation angle in degrees
* @param {boolean} [options.aria=true] - boolean indicating whether to include ARIA attributes in SVG output
* @param {string} [options.baseline='alphabetic'] - vertical text baseline
* @param {(boolean|Signal|Object)} [options.clip=false] - setting indicating whether to clip marks to a specified shape
* @param {string} [options.description] - text description of a mark for ARIA accessibility
* @param {string} [options.dir='ltr'] - text direction
* @param {number} [options.dx] - horizontal offset in pixels
* @param {number} [options.dy] - vertical offset in pixels
* @param {string} [options.ellipsis='\u2026'] - ellipsis string for text truncation
* @param {Object} [options.encode] - object containing visual encoding rules for mark properties
* @param {string} [options.font] - typeface
* @param {number} [options.fontSize] - font size in pixels
* @param {string} [options.fontStyle] - font style
* @param {string} [options.fontWeight] - font weight
* @param {Object} [options.from] - object describing the data a mark should visualize
* @param {boolean} [options.interactive=true] - boolean indicating whether a mark can serve as an input event source
* @param {(string|Object)} [options.key] - data field to use as a unique key for data binding
* @param {NonNegativeNumber} [options.limit=0] - maximum length of the text mark in pixels
* @param {string} [options.lineBreak] - delimiter for breaking text into multiple lines
* @param {number} [options.lineHeight] - height in pixels of each line in multi-line text
* @param {string} [options.name] - unique name
* @param {number} [options.radius=0] - polar coordinate radial offset in pixels
* @param {string} [options.role] - metadata string indicating the role of a mark
* @param {(string|Array<string>)} [options.text] - text to display
* @param {number} [options.theta=0] - polar coordinate angle in radians
* @param {Array<Trigger>} [options.triggers=[]] - list of triggers for modifying mark properties in response to signal changes
* @param {Object} [options.sort] - comparator for sorting mark items
* @param {Array<Transform>} [options.transforms=[]] - list of post-encoding transforms to apply after any "encode" blocks and which operate directly on mark scenegraph items
* @param {(string|Array<string>)} [options.style] - custom styles to apply to a mark
* @param {number} [options.zindex=0] - integer z-index indicating the layering of a mark relative to other marks
* @throws {TypeError} options argument must be an object
* @throws {TypeError} `type` option, if provided, must be equal to "text"
* @throws {Error} must provide valid options
* @returns {TextMark} text mark instance
*
* @example
* var mark = new TextMark({
*     'align': 'center'
* });
* // returns <TextMark>
*/
function TextMark( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof TextMark ) ) {
		if ( arguments.length === 0 ) {
			return new TextMark( {} );
		}
		return new TextMark( options );
	}
	if ( arguments.length === 0 ) {
		options = {};
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasProp( options, 'type' ) && options.type !== TYPE ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be equal to "%s". Option: `%s`.', 'type', TYPE, options.type ) );
	}
	options.type = TYPE;
	Mark.call( this, options );

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	this._type = TYPE;
	return this;
}

/*
* Inherit from a parent prototype.
*/
inherit( TextMark, Mark );

/**
* Constructor name.
*
* @private
* @name name
* @memberof TextMark
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( TextMark, 'name', 'TextMark' );

/**
* Horizontal text alignment.
*
* @name align
* @memberof TextMark.prototype
* @type {string}
* @default 'left'
*
* @example
* var mark = new TextMark({
*     'align': 'center'
* });
*
* var v = mark.align;
* // returns 'center'
*/
setReadWriteAccessor( TextMark.prototype, 'align', getAlign, setAlign );

/**
* Rotation angle in degrees.
*
* @name angle
* @memberof TextMark.prototype
* @type {number}
* @default 0
*
* @example
* var mark = new TextMark({
*     'angle': 45
* });
*
* var v = mark.angle;
* // returns 45
*/
setReadWriteAccessor( TextMark.prototype, 'angle', getAngle, setAngle );

/**
* Vertical text baseline.
*
* @name baseline
* @memberof TextMark.prototype
* @type {string}
* @default 'alphabetic'
*
* @example
* var mark = new TextMark({
*     'baseline': 'middle'
* });
*
* var v = mark.baseline;
* // returns 'middle'
*/
setReadWriteAccessor( TextMark.prototype, 'baseline', getBaseline, setBaseline );

/**
* Text direction.
*
* @name dir
* @memberof TextMark.prototype
* @type {string}
* @default 'ltr'
*
* @example
* var mark = new TextMark({
*     'dir': 'rtl'
* });
*
* var v = mark.dir;
* // returns 'rtl'
*/
setReadWriteAccessor( TextMark.prototype, 'dir', getDir, setDir );

/**
* Horizontal offset in pixels.
*
* @name dx
* @memberof TextMark.prototype
* @type {(number|void)}
*
* @example
* var mark = new TextMark({
*     'dx': 10
* });
*
* var v = mark.dx;
* // returns 10
*/
setReadWriteAccessor( TextMark.prototype, 'dx', getDx, setDx );

/**
* Vertical offset in pixels.
*
* @name dy
* @memberof TextMark.prototype
* @type {(number|void)}
*
* @example
* var mark = new TextMark({
*     'dy': 5
* });
*
* var v = mark.dy;
* // returns 5
*/
setReadWriteAccessor( TextMark.prototype, 'dy', getDy, setDy );

/**
* Ellipsis string for text truncation.
*
* @name ellipsis
* @memberof TextMark.prototype
* @type {string}
* @default '\u2026'
*
* @example
* var mark = new TextMark({
*     'ellipsis': '...'
* });
*
* var v = mark.ellipsis;
* // returns '...'
*/
setReadWriteAccessor( TextMark.prototype, 'ellipsis', getEllipsis, setEllipsis );

/**
* Typeface.
*
* @name font
* @memberof TextMark.prototype
* @type {(string|void)}
*
* @example
* var mark = new TextMark({
*     'font': 'Helvetica Neue'
* });
*
* var v = mark.font;
* // returns 'Helvetica Neue'
*/
setReadWriteAccessor( TextMark.prototype, 'font', getFont, setFont );

/**
* Font size in pixels.
*
* @name fontSize
* @memberof TextMark.prototype
* @type {(number|void)}
*
* @example
* var mark = new TextMark({
*     'fontSize': 14
* });
*
* var v = mark.fontSize;
* // returns 14
*/
setReadWriteAccessor( TextMark.prototype, 'fontSize', getFontSize, setFontSize );

/**
* Font style.
*
* @name fontStyle
* @memberof TextMark.prototype
* @type {(string|void)}
*
* @example
* var mark = new TextMark({
*     'fontStyle': 'italic'
* });
*
* var v = mark.fontStyle;
* // returns 'italic'
*/
setReadWriteAccessor( TextMark.prototype, 'fontStyle', getFontStyle, setFontStyle );

/**
* Font weight.
*
* @name fontWeight
* @memberof TextMark.prototype
* @type {(string|void)}
*
* @example
* var mark = new TextMark({
*     'fontWeight': 'bold'
* });
*
* var v = mark.fontWeight;
* // returns 'bold'
*/
setReadWriteAccessor( TextMark.prototype, 'fontWeight', getFontWeight, setFontWeight );

/**
* Maximum length of the text mark in pixels.
*
* @name limit
* @memberof TextMark.prototype
* @type {NonNegativeNumber}
* @default 0
*
* @example
* var mark = new TextMark({
*     'limit': 100
* });
*
* var v = mark.limit;
* // returns 100
*/
setReadWriteAccessor( TextMark.prototype, 'limit', getLimit, setLimit );

/**
* Line break delimiter.
*
* @name lineBreak
* @memberof TextMark.prototype
* @type {(string|void)}
*
* @example
* var mark = new TextMark({
*     'lineBreak': '\n'
* });
*
* var v = mark.lineBreak;
* // returns '\n'
*/
setReadWriteAccessor( TextMark.prototype, 'lineBreak', getLineBreak, setLineBreak );

/**
* Line height in pixels.
*
* @name lineHeight
* @memberof TextMark.prototype
* @type {(number|void)}
*
* @example
* var mark = new TextMark({
*     'lineHeight': 20
* });
*
* var v = mark.lineHeight;
* // returns 20
*/
setReadWriteAccessor( TextMark.prototype, 'lineHeight', getLineHeight, setLineHeight );

/**
* Mark properties.
*
* @name properties
* @memberof TextMark.prototype
* @type {Array<string>}
*
* @example
* var mark = new TextMark({});
*
* var v = mark.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( TextMark.prototype, 'properties', getProperties );

/**
* Polar coordinate radial offset in pixels.
*
* @name radius
* @memberof TextMark.prototype
* @type {number}
* @default 0
*
* @example
* var mark = new TextMark({
*     'radius': 50
* });
*
* var v = mark.radius;
* // returns 50
*/
setReadWriteAccessor( TextMark.prototype, 'radius', getRadius, setRadius );

/**
* Text to display.
*
* @name text
* @memberof TextMark.prototype
* @type {(string|Array<string>|void)}
*
* @example
* var mark = new TextMark({
*     'text': 'Hello, World!'
* });
*
* var v = mark.text;
* // returns 'Hello, World!'
*/
setReadWriteAccessor( TextMark.prototype, 'text', getText, setText );

/**
* Polar coordinate angle in radians.
*
* @name theta
* @memberof TextMark.prototype
* @type {number}
* @default 0
*
* @example
* var mark = new TextMark({
*     'theta': 1.5708
* });
*
* var v = mark.theta;
* // returns 1.5708
*/
setReadWriteAccessor( TextMark.prototype, 'theta', getTheta, setTheta );

/**
* Mark type.
*
* @name type
* @memberof TextMark.prototype
* @type {string}
* @default 'text'
*
* @example
* var mark = new TextMark({
*     'align': 'center'
* });
*
* var v = mark.type;
* // returns 'text'
*/
setReadWriteAccessor( TextMark.prototype, 'type', getType, setType );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof TextMark.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var mark = new TextMark({
*     'align': 'center'
* });
*
* var v = mark.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( TextMark.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = TextMark;
